-- 앞글자 일치로 바꾼다

@Test
@Transactional
void 앞글자() {
    em.clear();
    Member probe = new Member();
    probe.setUsername("m");

    ExampleMatcher matcher = ExampleMatcher.matching()
            .withIgnorePaths("age")
            .withMatcher("username",
                    ExampleMatcher.GenericPropertyMatchers.startsWith());

    System.out.println("건수: " +
            memberRepository.findAll(Example.of(probe, matcher)).size());
}

