-- 팀이 없는 회원은 못 찾는다

@Test
@Transactional
void 외부_조인() {
    em.persist(new Member("팀없음", 10));
    em.flush(); em.clear();

    Member probe = new Member();
    probe.setUsername("팀없음");

    System.out.println("건수: " + memberRepository.findAll(
            Example.of(probe,
                    ExampleMatcher.matching().withIgnorePaths("age")))
            .size());
}

