-- 페이징은 된다

@Test
@Transactional
void 페이징() {
    em.clear();
    Member probe = new Member();
    probe.setUsername("m");

    Page<Member> p = memberRepository.findAll(
            Example.of(probe, ExampleMatcher.matching()
                    .withIgnorePaths("age")
                    .withStringMatcher(ExampleMatcher.StringMatcher.STARTING)),
            PageRequest.of(0, 3, Sort.by("id")));
    System.out.println("전체: " + p.getTotalElements());
}

